from pathlib import Path
import base64
import shutil
import sys

PAYLOAD = """"""

def main():
    here = Path(__file__).resolve().parent
    candidates = [
        here.parent / "main.py",
        here.parent / "src" / "main.py",
        here.parent.parent / "main.py",
        here.parent.parent / "src" / "main.py",
    ]
    found = [p for p in candidates if p.is_file()]
    if len(found) != 1:
        raise RuntimeError("Nem találtam pontosan egy projekt main.py fájlt; nem történt módosítás.")

    target = found[0]
    current = target.read_text(encoding="utf-8")
    if "from testing.test_runner import TestRunnerDialog" not in current:
        raise RuntimeError("Nem a várt 0.6.0-TEST main.py található; nem történt módosítás.")

    backup = target.with_name(target.name + ".bak_0.6.1")
    if backup.exists():
        raise RuntimeError(f"A biztonsági mentés már létezik: {backup}")

    new_text = base64.b64decode(PAYLOAD).decode("utf-8")

    required = [
        "from testing.test_runner import TestRunnerDialog",
        "def open_test_lab(self):",
        "def rename(self):",
        "def analyze(self):",
        'allowed_statuses = {"OK"}',
        'item.status = "Névütközés"',
        "destination.mkdir(parents=True, exist_ok=True)",
    ]
    missing = [x for x in required if x not in new_text]
    if missing:
        raise RuntimeError("A beépített 0.6.1 fájl ellenőrzése sikertelen: " + ", ".join(missing))

    shutil.copy2(target, backup)
    target.write_text(new_text, encoding="utf-8")

    print("PATCH SIKERES")
    print(f"Main: {target}")
    print(f"Backup: {backup}")
    print("Meglévő célfájl: SOHA nem írható felül.")
    print("Részleges célütközés: csak az ütköző fájl marad ki.")
    print("Nem létező kimeneti mappa: automatikusan létrejön.")
    print("0.6.0-TEST Tesztlabor: MEGMARADT.")

if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"PATCH HIBA: {exc}")
        sys.exit(1)
